import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

export function Magnetic() {
  const container = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      const btn = container.current!.querySelector<HTMLButtonElement>(".magnetic")!;
      const xTo = gsap.quickTo(btn, "x", { duration: {{duration}}, ease: "{{ease}}" });
      const yTo = gsap.quickTo(btn, "y", { duration: {{duration}}, ease: "{{ease}}" });
      const move = (e: MouseEvent) => {
        const r = btn.getBoundingClientRect();
        xTo((e.clientX - r.left - r.width / 2) * {{strength}});
        yTo((e.clientY - r.top - r.height / 2) * {{strength}});
      };
      const leave = () => {
        xTo(0);
        yTo(0);
      };
      btn.addEventListener("mousemove", move);
      btn.addEventListener("mouseleave", leave);
      return () => {
        btn.removeEventListener("mousemove", move);
        btn.removeEventListener("mouseleave", leave);
      };
    },
    { scope: container },
  );

  return (
    <div ref={container}>
      <button className="magnetic">Hover me</button>
    </div>
  );
}
